@page "/book-appointment"
@rendermode InteractiveServer
@using sv_d40a220d52ad481985fa336425fbc182.Models
@using sv_d40a220d52ad481985fa336425fbc182.Services
@inject AppointmentService AppointmentSvc

<PageTitle>Book Appointment</PageTitle>

<h3>Book a Medical Appointment</h3>

<EditForm EditContext="_editContext" OnValidSubmit="HandleSubmit" FormName="BookAppointment">
    <DataAnnotationsValidator />

    @* ── STEP 1 ── *@
    <fieldset>
        <legend>Patient Information</legend>

        <div class="mb-3">
            <label class="form-label" for="patientName">Patient Name</label>
            <InputText id="patientName" class="form-control" @bind-Value="Model.PatientName" />
            <ValidationMessage For="() => Model.PatientName" />
        </div>

        <div class="mb-3">
            <label class="form-label" for="email">Email</label>
            <InputText id="email" class="form-control" @bind-Value="Model.Email" />
            <ValidationMessage For="() => Model.Email" />
        </div>

        <div class="mb-3">
            <label class="form-label" for="phone">Phone</label>
            <InputText id="phone" class="form-control" @bind-Value="Model.Phone" />
            <ValidationMessage For="() => Model.Phone" />
        </div>

        <div class="mb-3">
            <label class="form-label" for="insurance">Insurance Provider</label>
            <InputSelect id="insurance" class="form-select" @bind-Value="Model.InsuranceProvider">
                <option value="">-- Select --</option>
                <option value="Aetna">Aetna</option>
                <option value="BlueCross">BlueCross</option>
                <option value="Cigna">Cigna</option>
                <option value="UnitedHealth">UnitedHealth</option>
                <option value="None">None</option>
            </InputSelect>
            <ValidationMessage For="() => Model.InsuranceProvider" />
        </div>

        @if (!_showStep2)
        {
            <button type="button" class="btn btn-primary" @onclick="ProceedToStep2">
                Next
            </button>
        }
    </fieldset>

    @* ── STEP 2 ── *@
    @if (_showStep2)
    {
        <fieldset class="mt-4">
            <legend>Appointment Details</legend>

            <div class="mb-3">
                <label class="form-label" for="doctor">Preferred Doctor</label>
                <InputSelect id="doctor" class="form-select"
                             @bind-Value="Model.Doctor"
                             @bind-Value:after="OnDoctorChanged">
                    <option value="">-- Select --</option>
                    @foreach (var doc in _doctors)
                    {
                        <option value="@doc">@doc</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => Model.Doctor" />
            </div>

            <div class="mb-3">
                <label class="form-label" for="appointmentDate">Date</label>
                <InputDate id="appointmentDate" class="form-control"
                           @bind-Value="Model.AppointmentDate"
                           @bind-Value:after="OnDateChanged" />
                <ValidationMessage For="() => Model.AppointmentDate" />
                @if (_dateInPastError)
                {
                    <div class="validation-message">Date must be in the future.</div>
                }
            </div>

            <div class="mb-3">
                <label class="form-label" for="timeSlot">Time Slot</label>
                <InputSelect id="timeSlot" class="form-select" @bind-Value="Model.TimeSlot">
                    <option value="">-- Select --</option>
                    @foreach (var slot in _timeSlots)
                    {
                        <option value="@slot">@slot</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => Model.TimeSlot" />
            </div>

            <div class="mb-3">
                <label class="form-label" for="reason">Reason for Visit</label>
                <InputTextArea id="reason" class="form-control" rows="3"
                               @bind-Value="Model.ReasonForVisit" />
                <ValidationMessage For="() => Model.ReasonForVisit" />
            </div>

            <button type="button" class="btn btn-outline-secondary me-2" @onclick="BackToStep1">
                Back
            </button>
            <button type="button" class="btn btn-info me-2" @onclick="CheckAvailability">
                Check Availability
            </button>
            <button type="submit" class="btn btn-success" disabled="@(!_availabilityChecked)">
                Book Appointment
            </button>
        </fieldset>
    }
</EditForm>

@if (_submitted)
{
    <div class="alert alert-success mt-4">
        Appointment booked successfully for <strong>@Model.PatientName</strong>
        with <strong>@Model.Doctor</strong>
        on @Model.AppointmentDate?.ToString("MMM dd, yyyy") at @Model.TimeSlot.
    </div>
}

@code {
    private AppointmentFormModel Model { get; set; } = new();
    private EditContext _editContext = default!;
    private ValidationMessageStore _serverErrors = default!;

    private bool _showStep2;
    private bool _submitted;
    private bool _availabilityChecked;
    private bool _dateInPastError;

    private List<string> _doctors = [];
    private List<string> _timeSlots = [];

    // Fields that belong to step 1 for partial validation
    private static readonly string[] Step1Fields =
        [nameof(AppointmentFormModel.PatientName),
         nameof(AppointmentFormModel.Email),
         nameof(AppointmentFormModel.Phone),
         nameof(AppointmentFormModel.InsuranceProvider)];

    protected override async Task OnInitializedAsync()
    {
        _editContext = new EditContext(Model);
        _serverErrors = new ValidationMessageStore(_editContext);

        // Clear server errors when the user edits a field
        _editContext.OnFieldChanged += (_, args) =>
        {
            _serverErrors.Clear(args.FieldIdentifier);
            _availabilityChecked = false;
            _editContext.NotifyValidationStateChanged();
        };

        _doctors = await AppointmentSvc.GetDoctorsAsync();
    }

    private void ProceedToStep2()
    {
        // Validate only step 1 fields
        _serverErrors.Clear();
        var isValid = _editContext.Validate();

        if (!isValid)
        {
            // Check if all errors are on step-2-only fields (which haven't been filled yet)
            var messages = _editContext.GetValidationMessages();
            var step1FieldIdentifiers = Step1Fields
                .Select(f => _editContext.Field(f));
            var step1Errors = step1FieldIdentifiers
                .SelectMany(fi => _editContext.GetValidationMessages(fi));

            if (step1Errors.Any())
                return;
        }

        _showStep2 = true;
    }

    private void BackToStep1()
    {
        _showStep2 = false;
        _availabilityChecked = false;
    }

    private async Task OnDoctorChanged()
    {
        _availabilityChecked = false;
        await LoadTimeSlots();
    }

    private async Task OnDateChanged()
    {
        _availabilityChecked = false;
        _dateInPastError = Model.AppointmentDate.HasValue
                           && Model.AppointmentDate.Value <= DateOnly.FromDateTime(DateTime.Today);
        await LoadTimeSlots();
    }

    private async Task LoadTimeSlots()
    {
        if (!string.IsNullOrEmpty(Model.Doctor) && Model.AppointmentDate.HasValue)
        {
            _timeSlots = await AppointmentSvc.GetAvailableTimeSlotsAsync(
                Model.Doctor, Model.AppointmentDate.Value);
        }
        else
        {
            _timeSlots = [];
        }

        // Reset selection when slots reload
        Model.TimeSlot = null;
    }

    private async Task CheckAvailability()
    {
        _serverErrors.Clear();
        _dateInPastError = Model.AppointmentDate.HasValue
                           && Model.AppointmentDate.Value <= DateOnly.FromDateTime(DateTime.Today);

        if (!_editContext.Validate() || _dateInPastError)
            return;

        var result = await AppointmentSvc.ValidatePatientAsync(Model);

        if (!result.IsValid)
        {
            foreach (var (field, message) in result.Errors)
            {
                _serverErrors.Add(_editContext.Field(field), message);
            }

            _editContext.NotifyValidationStateChanged();
            _availabilityChecked = false;
            return;
        }

        _availabilityChecked = true;
    }

    private void HandleSubmit()
    {
        if (!_availabilityChecked || _dateInPastError)
            return;

        _submitted = true;
    }
}

