+            var step1Errors = step1FieldIdentifiers
+                .SelectMany(fi => _editContext.GetValidationMessages(fi));
+
+            if (step1Errors.Any())
+                return;
+        }
+
+        _showStep2 = true;
+    }
+
+    private void BackToStep1()
+    {
+        _showStep2 = false;
+        _availabilityChecked = false;
+    }
+
+    private async Task OnDoctorChanged()
+    {
+        _availabilityChecked = false;
+        await LoadTimeSlots();
+    }
+
+    private async Task OnDateChanged()
+    {
+        _availabilityChecked = false;
+        _dateInPastError = Model.AppointmentDate.HasValue
+                           && Model.AppointmentDate.Value <= DateOnly.FromDateTime(DateTime.Today);
+        await LoadTimeSlots();
+    }
+
+    private async Task LoadTimeSlots()
+    {
+        if (!string.IsNullOrEmpty(Model.Doctor) && Model.AppointmentDate.HasValue)
+        {
+            _timeSlots = await AppointmentSvc.GetAvailableTimeSlotsAsync(
+                Model.Doctor, Model.AppointmentDate.Value);
+        }
+        else
+        {
+            _timeSlots = [];
+        }
+
+        // Reset selection when slots reload
+        Model.TimeSlot = null;
+    }
+
+    private async Task CheckAvailability()
+    {
+        _serverErrors.Clear();
+        _dateInPastError = Model.AppointmentDate.HasValue
+                           && Model.AppointmentDate.Value <= DateOnly.FromDateTime(DateTime.Today);
+
+        if (!_editContext.Validate() || _dateInPastError)
+            return;
+
+        var result = await AppointmentSvc.ValidatePatientAsync(Model);
+
+        if (!result.IsValid)
+        {
+            foreach (var (field, message) in result.Errors)
+            {
+                _serverErrors.Add(_editContext.Field(field), message);
+            }
+
+            _editContext.NotifyValidationStateChanged();
+            _availabilityChecked = false;
+            return;
+        }
+
+        _availabilityChecked = true;
+    }
+
+    private void HandleSubmit()
+    {
+        if (!_availabilityChecked || _dateInPastError)
+            return;
+
+        _submitted = true;
+    }
+}
+

